def doubling(n,mod):
    a,res,c,c1 = 1,0,1,0
    while n > 0:
        if n&1:
            res = (a*pow(10,c1,mod)+res)%mod
            c1 += c
        a = (a+a*pow(10,c,mod))%mod
        n >>= 1
        c *= 2
    return res

def euler_phi(n):
    res = n
    for x in range(2,n+1):
        if x ** 2 > n:
            break
        if n%x==0:
            res = res//x * (x-1)
            while n%x==0:
                n //= x
    if n!=1:
        res = res//n * (n-1)
    return res

def divisors(n):
    lower_divisors, upper_divisors = [], []
    i = 1
    while i * i <= n:
        if n % i == 0:
            lower_divisors.append(i)
            if i != n // i:
                upper_divisors.append(n // i)
        i += 1
    return lower_divisors + upper_divisors[::-1]

