def Ternary_Search_Maximize_Integer(L, R, f, arg=False):
    """ 三分探索によって, 整数を定義域とする関数 f の [L,R] における最大値を求める.

    f: [L,R] 内で上に凸または単調増加
    """
    while (R-L)>3:
        a=(2*L+R)//3
        b=(L+2*R)//3

        p=f(a); q=f(b)
        if p>=q:
            R=b
        else:
            L=a

    a=(2*L+R)//3
    b=(L+2*R)//3

    if arg:
        y,argx=f(L),L
        for x in [a,b,R]:
            p=f(x)
            if y<p:
                y,argx=p,x
        return y,argx
    else:
        return max(f(L),f(a),f(b),f(R))

