def bsgs2(a, b, r, f, fr):
    # f^x(a) = b (mod m) たる最小のx
    # r = int(m**0.5) + 1, fr:f^r
    if a == b:
        return 0
    # baby step
    baby = {}
    for i in range(r):
        baby[b] = i
        b = f(b)
    # giant step
    for j in range(1, r + 3):
        a = fr(a)
        if a in baby:
            return j * r - baby[a]
    return -1


