class UnionFind:
    def __init__(self, n):
        self.n = n
        self.parents = [-1] * n

    def find(self, x):
        if self.parents[x] < 0:
            return x
        else:
            self.parents[x] = self.find(self.parents[x]) # 経路圧縮
        return self.parents[x]

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)

        if x == y:
            return

        if self.parents[x] > self.parents[y]: # ランクによる軽量化
            x, y = y, x

        self.parents[x] += self.parents[y] # 負の数が大きくなるほど、ノードの数が多いということ
        self.parents[y] = x

