    if n == 0:
        return piece
    if n == 1:
        return list(map(list, zip(*piece[::-1])))
    if n == 2:
        return list(reversed([p[::-1] for p in piece]))
    if n == 3:
        return list(map(list, zip(*piece)))[::-1]


