Y.sort()

def solve(A,d):
  h=A[:]
  heapq.heapify(h)
  for i in range(N):
    l=heapq.heappushpop(h, A[i]-d)
  ans=0
  for a in A:
    if a<l:
      ans+=l-a
    elif a>l+d:
      ans+=a-(l+d)
  return ans

#判定用関数
def judge(d):
  if solve(X,d)+solve(Y,d)<K:
    return False
  else:
    return True

