def solveLIS(lst):
    if lst == []:
        return 0
    LIS = [lst[0]]
    ex = []
    for i in range(len(lst)):
        if lst[i] > LIS[-1]:
            ex.append(len(LIS))
            LIS.append(lst[i])

        else:
            x = bisect.bisect_left(LIS,lst[i])
            LIS[x] = lst[i]
            ex.append(x)
    return LIS, ex


