from io import BytesIO, IOBase

def solve(a):
    a1 = []
    n1 = len(a)
    for i in range(1, n1):
        a1.append(a[0] ^ a[i])

    basis = []
    for elem in a1:
        elemcpy = elem
        for elem2 in basis:
            if elemcpy ^ elem2 < elemcpy:
                elemcpy = elemcpy ^ elem2
        if elemcpy != 0:
            basis.append(elemcpy)
            basis.sort(reverse=True)

    maxx = 0
    for elem in basis:
        if elem ^ maxx > maxx:
            maxx = elem ^ maxx

    return maxx

def main():
